      {"q": "Quin exemple il·lustra la prefixació?", "o": ["desfer", "claror", "rentadora"], "e": "«Desfer» incorpora el prefix des- a «fer»."},
      {"q": "Quina afirmació sobre els neologismes és adequada?", "o": ["Poden designar realitats noves o noves accepcions", "Sempre són manlleus sense adaptar", "Només apareixen en la llengua col·loquial"], "e": "Una novetat lèxica pot ser una forma nova o un sentit nou d'una forma existent."},
      {"q": "Quina és la diferència bàsica entre un calc i un manlleu no adaptat?", "o": ["El calc reproduïx el model amb recursos propis; el manlleu conserva una forma estrangera", "El calc és sempre oral; el manlleu, sempre escrit", "El calc és una paraula antiga; el manlleu, una forma dialectal"], "e": "El calc tradueix o replica el model; el manlleu incorpora la forma d'origen."},
      {"q": "Quina opció conté una forma verbal parasintètica?", "o": ["assecar", "sec", "sequedat"], "e": "«Assecar» es forma amb prefix i terminació verbal sobre la base adjectival."},
      {"q": "Quin mecanisme dona lloc a «adormir»?", "o": ["Parasíntesi", "Composició", "Acronímia"], "e": "La formació verbal combina prefix i terminació verbal sobre «dormir»."},
      {"q": "Quina paraula és un substantiu habilitat a partir d'una forma verbal?", "o": ["el berenar", "berenador", "berenable"], "e": "En «el berenar», l'infinitiu funciona com a substantiu."},
      {"q": "En «El perquè de la proposta encara no és clar», «perquè» és...", "o": ["un substantiu", "una conjunció", "un pronom relatiu"], "e": "Com a nom, «perquè» significa 'motiu' i admet determinant."},
      {"q": "Quina opció és un exemple de lexicalització d'una forma gramatical?", "o": ["un no rotund", "no vindrà", "no obstant això"], "e": "En «un no», l'adverbi de negació funciona com a substantiu."},
      {"q": "En la creació d'un neologisme, què cal valorar especialment?", "o": ["La necessitat denominativa, la transparència i l'adequació al registre", "Que coincidisca lletra per lletra amb una forma estrangera", "Que siga més llarg que la forma que substituïx"], "e": "La fixació lèxica considera la necessitat, la claredat i l'adequació de la proposta."},
      {"q": "Quin recurs és preferible quan ja hi ha una denominació valenciana precisa i consolidada?", "o": ["Usar la forma valenciana consolidada", "Calcar literalment qualsevol novetat estrangera", "Mantindre sempre la forma original sense adaptar"], "e": "La precisió i la normativa orienten la tria lèxica."},
      {"q": "Quina afirmació sobre els manlleus adaptats és correcta?", "o": ["S'ajusten a les convencions formals de la llengua receptora", "Conserven necessàriament la grafia original", "Són sempre incorrectes"], "e": "Un manlleu pot adaptar-se gràficament i fonèticament a la llengua."},
      {"q": "Quin exemple mostra una paraula formada per composició?", "o": ["allioli", "enriquir", "lentament"], "e": "«Allioli» és una forma composta; «enriquir» i «lentament» són derivats."},
      {"q": "Quin exemple conté un prefix que aporta valor de repetició?", "o": ["reobrir", "obertura", "obert"], "e": "El prefix re- pot indicar que l'acció es torna a fer."},
      {"q": "Què s'anomena conversió o habilitació?", "o": ["L'ús d'una forma en una categoria diferent de l'habitual", "La traducció d'un text complet", "La unió de dos mots amb guionet"], "e": "La conversió modifica la funció categorial en el context."},
