      {"q": "Escriu l'adjectiu per a la variació vinculada a les àrees geogràfiques.", "a": ["diatòpic"], "e": "El DNV definix «diatòpic» en relació amb les àrees geogràfiques."},
      {"q": "Escriu l'adjectiu per a la variació relacionada amb els registres lingüístics.", "a": ["diafàsic"], "e": "El DNV relaciona «diafàsic» amb els registres."},
      {"q": "Escriu l'adjectiu per a la variació relacionada amb els nivells socioculturals dels parlants.", "a": ["diastràtic"], "e": "El DNV relaciona «diastràtic» amb els nivells socioculturals."},
      {"q": "Escriu l'adjectiu que significa «relatiu a l'evolució al llarg del temps».", "a": ["diacrònic"], "e": "El DNV definix «diacrònic» com allò que considera l'evolució al llarg del temps."},
      {"q": "Escriu el terme per a la manera d'usar la llengua adequada a una situació comunicativa.", "a": ["registre"], "e": "El registre s'ajusta a la situació, al destinatari i al propòsit."},
      {"q": "Escriu el terme per a una modalitat geogràfica d'una llengua.", "a": ["dialecte"], "e": "El DNV definix el dialecte com una varietat geogràfica, històrica o social d'una llengua."},
      {"q": "Escriu l'adjectiu «diafàsic» en femení singular.", "a": ["diafàsica"], "e": "L'adjectiu varia en gènere: diafàsic, diafàsica."},
      {"q": "Escriu l'adjectiu «diatòpic» en femení singular.", "a": ["diatòpica"], "e": "L'adjectiu varia en gènere: diatòpic, diatòpica."},
      {"q": "Escriu l’adjectiu femení relacionat amb la variació dels nivells socioculturals.", "a": ["diastràtica"], "e": "«Diastràtic» concorda en femení com «diastràtica»."}
    ]
  },
  {
    "id": "287bf6e0-a2f4-5a70-9444-e18fa12cf252", "type": "c2_lex_pragmatica_figurats", "sort_order": 22,
    "title": "Semàntica pragmàtica i usos figurats", "name": "Inferències, pressuposicions, sobreentesos i figures retòriques",
    "content": "Interpreta les substitucions, les pressuposicions, els sobreentesos, les inferències i la ironia, i distingix comparació, metàfora, metonímia i sinècdoque en usos lèxics figurats, d'acord amb el Quadern C2 (3.2.3).", "icon": "🎭", "color": "#FFE0B2",
    "exercises": [
      {"q": "Què estudia la pragmàtica lingüística?", "o": ["La llengua en relació amb l'ús, els usuaris i les inferències", "Només l'origen històric de les paraules", "La formació del plural dels noms"], "e": "El DNV definix la pragmàtica com la part de la lingüística que estudia la llengua en relació amb l'ús i els usuaris."},
      {"q": "Què és una inferència?", "o": ["Una conclusió que es deduïx a partir d'una o més dades o proposicions", "Una paraula que substituïx un nom propi", "Una forma antiga d'un verb"], "e": "Una inferència és un raonament pel qual s'arriba a una conclusió a partir d'informació disponible."},
      {"q": "Què és una pressuposició en un enunciat?", "o": ["Una informació que es dona per existent o vàlida perquè l'enunciat tinga sentit", "Una informació que sempre es diu explícitament", "Una comparació introduïda per «com»"], "e": "La pressuposició és informació de fons que l'enunciat dona per assumida."},
      {"q": "Què és un sobreentés?", "o": ["Allò que no s'expressa directament però que es dona per entés en el context", "Una afirmació literal i completa", "Una paraula amb significat oposat a una altra"], "e": "El sobreentés és un contingut que els interlocutors recuperen a partir del context."},
      {"q": "En «Carme ha deixat de fumar», què es pressuposa?", "o": ["Que Carme fumava abans", "Que Carme no ha fumat mai", "Que Carme ha començat a fumar"], "e": "«Deixar de» pressuposa que l'activitat es feia abans."},
      {"q": "En «Pau també vindrà», què pressuposa «també»?", "o": ["Que una altra persona vindrà o ve", "Que Pau no vindrà", "Que Pau ja ha arribat"], "e": "«També» incorpora l'expectativa que hi ha una altra persona o element que compartix l'acció."},
      {"q": "Si algú diu «Ací fa molt de fred» mentre mira una finestra oberta, quina inferència pragmàtica és probable?", "o": ["Que vol que algú tanque la finestra", "Que vol que obrin una altra finestra", "Que està fent una comparació literal"], "e": "El context permet inferir una petició indirecta, encara que no s'haja formulat com una ordre."},
      {"q": "Quina expressió conté una metàfora?", "o": ["La ciutat és un formiguer", "La ciutat té molts carrers", "La ciutat està al costat del riu"], "e": "«Formiguer» s'aplica figuradament a una ciutat plena d'activitat per semblança."},
      {"q": "Quina expressió conté una comparació explícita?", "o": ["Corregué com una daina", "La seua veu era seda", "La corona va anunciar la decisió"], "e": "La comparació establix una semblança amb el nexe «com»."},
      {"q": "Quina expressió és un exemple de metonímia?", "o": ["Va llegir tot Joan Fuster", "Les seues idees eren llavors", "És tan fort com un roure"], "e": "En «llegir Joan Fuster», el nom de l'autor designa les seues obres."},
      {"q": "Quina expressió és un exemple de sinècdoque?", "o": ["Hi havia cent caps de bestiar al corral", "El govern va respondre a la premsa", "El temps és or"], "e": "«Caps» designa una part per a referir-se als animals sencers."},
      {"q": "Quina és la diferència principal entre metonímia i metàfora?", "o": ["La metonímia es basa en una relació de contigüitat; la metàfora, en una semblança", "La metonímia és sempre una comparació amb «com»", "La metàfora només s'usa en textos científics"], "e": "La metonímia relaciona referents contigus; la metàfora projecta un nom per semblança."},
      {"q": "En «El palau ha publicat un comunicat», quin recurs permet que «palau» designe la institució?", "o": ["Metonímia", "Comparació", "Antonomàsia"], "e": "El lloc o edifici s'usa per a designar la institució que hi té la seu."},
      {"q": "Quina frase és irònica si es diu mentre plou a bots i barrals?", "o": ["Quin dia més esplèndid per a anar de pícnic!", "La pluja mulla el carrer", "Hui portaré un paraigua"], "e": "El context fa que l'elogi expresse el contrari i tinga un valor irònic."},
      {"q": "Quin tret definix la ironia retòrica?", "o": ["Dir el contrari d'allò que es vol donar a entendre, sovint amb intenció de burla", "Descriure literalment un fet", "Substituir el tot per una part"], "e": "El DNV definix la ironia retòrica com dir el contrari del que es vol donar a entendre."},
      {"q": "Quina figura pren el contingut pel continent?", "o": ["Metonímia", "Comparació", "Hipèrbole"], "e": "La metonímia pot designar el contingut pel recipient que el conté."},
      {"q": "Quina figura pren la part pel tot o el tot per la part?", "o": ["Sinècdoque", "Metàfora", "Ironia"], "e": "La sinècdoque amplia o restringix el significat prenent el tot per la part o la part pel tot."},
      {"q": "Quina opció conté una substitució metonímica d'autor per obra?", "o": ["Escoltem Mozart cada vesprada", "La música sona molt alta", "La melodia és com un riu"], "e": "El nom del compositor pot designar la seua música o les seues obres."},
      {"q": "En «Els peus de la muntanya estaven coberts de boira», quin recurs apareix?", "o": ["Metàfora", "Sinècdoque", "Ironia"], "e": "«Peus» s'aplica a una part de la muntanya per semblança amb el cos humà."},
      {"q": "Quina frase conté una comparació i no una metàfora directa?", "o": ["La seua memòria és com un arxiu", "La seua memòria és un arxiu", "L'arxiu guarda els documents"], "e": "El nexe «com» establix explícitament la semblança."},
      {"q": "En «La sala sencera va aplaudir», quin sentit pot tindre «la sala»?", "o": ["Les persones que hi ha dins de la sala", "Només les parets de l'espai", "El mobiliari de l'edifici"], "e": "El lloc pot designar metonímicament les persones que l'ocupen."},
      {"q": "Quin enunciat conté un sobreentés contextual i no una afirmació explícita?", "o": ["Ja és tard i demà matinem", "El rellotge marca les deu", "Demà el sol eixirà"], "e": "En el context adequat, la primera frase pot sobreentendre una invitació a acabar la conversa."},
      {"q": "Quina és una pressuposició de «La directora ha tornat a convocar la reunió»?", "o": ["Que ja havia convocat la reunió abans", "Que la reunió no tindrà lloc", "Que no hi ha cap directora"], "e": "«Tornar a» pressuposa que l'acció ja s'havia produït."},
      {"q": "Quina és una inferència probable de «El carrer està inundat i els vehicles no passen»?", "o": ["La circulació pot estar interrompuda", "No hi ha cap vehicle al municipi", "El carrer està asfaltat"], "e": "La informació permet inferir que el trànsit no pot circular amb normalitat."},
      {"q": "Quina expressió usa el tot per la part?", "o": ["El poble sencer va eixir al carrer", "Va comprar una mà de plàtans", "El despatx va telefonar"], "e": "«El poble sencer» pot designar metonímicament els habitants del poble."},
      {"q": "Quina expressió usa el lloc per a designar les persones que hi viuen?", "o": ["Necessitem més mans per a acabar l'obra", "El museu ha adquirit un quadre", "L'alcaldia ha respost"], "e": "«El poble sencer» pot designar metonímicament els seus habitants."},
      {"q": "Quina frase conté una metàfora lexicalitzada?", "o": ["Va perdre el fil de la conversa", "Va perdre el quadern a classe", "Va deixar el fil damunt de la taula"], "e": "«Perdre el fil» usa la imatge d'un fil per a expressar la pèrdua de continuïtat o comprensió."},
      {"q": "Quin ús de «fred» és figurat en «Va rebre la notícia amb fredor»?", "o": ["Indica una actitud distant o poc emotiva", "Indica una temperatura baixa", "Indica un fenomen meteorològic"], "e": "La fredor s'aplica metafòricament a una actitud distant."},
      {"q": "En «La corona va aprovar la proposta», quina relació permet la substitució?", "o": ["El símbol o atribut pel poder que representa", "La part pel tot d'un animal", "Una semblança de color"], "e": "La corona pot designar metonímicament la monarquia o el poder reial."},
      {"q": "Quin recurs ajuda a interpretar una ironia?", "o": ["El context i la diferència entre el sentit literal i la intenció", "Només el nombre de paraules", "L'ordre alfabètic de les paraules"], "e": "La ironia depén del context, del to i de la intenció atribuïda al parlant."},
      {"q": "Quina opció descriu una metàfora?", "o": ["Una paraula s'usa per a expressar una realitat semblant", "Un nom de lloc substituïx un nom de persona", "Una expressió es repetix literalment"], "e": "La metàfora trasllada una denominació a una altra realitat per una semblança."},
      {"q": "Quina opció descriu una comparació retòrica?", "o": ["Relaciona dos termes per una semblança expressada gramaticalment", "Designa el contingut pel continent", "Diu el contrari del que es vol donar a entendre"], "e": "La comparació establix explícitament una semblança entre termes."},
      {"q": "En «Pots deixar-me el teu bolígraf?» dins d’una conversa, quina intenció és probable?", "o": ["Fer una petició indirecta", "Preguntar només per la capacitat física de l’interlocutor", "Afirmar que el bolígraf és propi"], "e": "En context, una pregunta sobre possibilitat pot funcionar com una petició indirecta."},
      {"q": "Escriu el terme per a la figura que es basa en una semblança entre dos realitats.", "a": ["metàfora"], "e": "El DNV definix la metàfora com l'ús d'una paraula per semblança amb una altra realitat."},
      {"q": "Escriu el terme per a la figura basada en una relació de contigüitat entre referents.", "a": ["metonímia"], "e": "La metonímia designa una cosa amb el nom d'una altra contigua."},
      {"q": "Escriu el terme per a la figura que pren el tot per la part o la part pel tot.", "a": ["sinècdoque"], "e": "El DNV definix així la sinècdoque."},
      {"q": "Escriu el terme per a la figura que establix explícitament una semblança entre dos termes.", "a": ["comparació"], "e": "La comparació retòrica establix una semblança per mitjà de vincles gramaticals."},
      {"q": "Escriu el terme per a la figura que pot dir el contrari d'allò que es vol donar a entendre.", "a": ["ironia"], "e": "La ironia retòrica comunica un sentit diferent o contrari del literal."},
      {"q": "Escriu el terme per al raonament que passa d'unes dades a una conclusió.", "a": ["inferència"], "e": "La inferència és un raonament que conduïx a una conclusió."},
      {"q": "Escriu el terme per a la informació que es dona per assumida en un enunciat.", "a": ["pressuposició"], "e": "La pressuposició és una informació de fons donada per vàlida."},
      {"q": "Escriu el terme per a allò que no es diu directament però es dona per entés.", "a": ["sobreentés", "sobreentès"], "e": "El DNV admet «sobreentés» i «sobreentès»."},
      {"q": "Escriu la branca de la lingüística que estudia la llengua en relació amb l'ús i els usuaris.", "a": ["pragmàtica"], "e": "El DNV definix la pragmàtica lingüística en estos termes."}
